function CBMCalculate() {
    if (CURRENTSHIPMENT.container) {
        let length = $(`#Input-Length`).val();
        let width = $(`#Input-Width`).val();
        let height = $(`#Input-Height`).val();
        let cbm = CURRENTSHIPMENT.filledcmb;
        if (length && length > 0 && width && width > 0 && height && height > 0) {
            if ($(`#Input-AddWithCartoonCount`).prop('checked')) {
                let resultCartoon = getCartoonNumber();
                if (resultCartoon.isValid) {
                    if (resultCartoon.isRanged) {
                        if (resultCartoon.start < resultCartoon.end) {
                            cbm += ((length * width * height) / 1000000) * ((resultCartoon.end - resultCartoon.start) + 1);
                        } else {
                            Lobibox.notify('warning', { position: 'top right', msg: "Please enter valid Cartonn Range" });
                            return;
                        }
                    } else {
                        cbm += (length * width * height) / 1000000;
                    }
                }
            } else {
                cbm += (length * width * height) / 1000000;
            }
        }

        if (!isNaN(cbm.toFixed(2)) && cbm > 0) {
            let perecentage = (cbm / SYSTEMCONTAINER[$(`#container`).dropdown('get value')].cbm) * 100;
            $('#example5').progress('set progress', cbm);
            if (cbm > 0 && !$('#example5').transition('is visible')) {
                $('#example5').transition('slide  right', 1000);
            } else if (cbm <= 0 && $('#example5').transition('is visible')) {
                $('#example5').transition('slide  right', 1000);
            }
            $(`#View-ContainerFeet`).html(`<span class="ui mini black circular label">${Math.round(perecentage)}%</span> ${cbm.toFixed(2)} CBM Completed <small> of ${SYSTEMCONTAINER[$(`#container`).dropdown('get value')].cbm} CBM | ${SYSTEMCONTAINER[$(`#container`).dropdown('get value')].name}</small>`);
            $(`#View-CBMPerCartoon`).html(`<b>${cbm.toFixed(2)}</b> CBM <small>in Centimetre</small>`);
        }
    }
}

