function getCartoonNumber() {
    let resultCartoon = {
        isValid: false,
        isRanged: false,
        start: 0,
        end: 0,
        prefix: '',
        profix: ''
    };
    let start = $(`#Input-Start`).val();
    let end = $(`#Input-End`).val();
    if (start && end) {
        start = start.match(/[^\d]+|\d+/g);
        end = end.match(/[^\d]+|\d+/g);
        resultCartoon.isValid = true;
        resultCartoon.isRanged = true;
        if (start[0].match(/^[A-Za-z]+$/) && end[0].match(/^[A-Za-z]+$/)) {
            resultCartoon.prefix = start[0].trim().toUpperCase();
            resultCartoon.start = parseInt(start[1]);
            resultCartoon.end = parseInt(end[1]);
        } else {
            if (start.length > 1) {
                resultCartoon.profix = start[1].trim().toUpperCase();
            }
            resultCartoon.start = parseInt(start[0]);
            resultCartoon.end = parseInt(end[0]);
        }
    } else if (start) {
        resultCartoon.isValid = true;
        resultCartoon.start = start.trim().toUpperCase();
    }
    return resultCartoon;
}

