$('#save-shipment').click(saveShipment);

function arragedCartoonPacked(carton, length, width, heigth, weight) {
    let arrangedResult = {
        carton: carton,
        customer: $(`#Input-CustomerName`).val().trim().toUpperCase(),
        products: [],
        weight: weight,
        length: length,
        width: width,
        heigth: heigth,
        cbm: (length > 0 && width > 0 && heigth > 0) ? ((length * width * heigth) / 1000000) : 0,
        isPacking: $(`#Input-Packing`).prop('checked'),
        isWoodboxg: $(`#Input-WoodBox`).prop('checked'),
        status: 'In Process',
        statuscode: 0,
        marks: $(`#marks-numbers`).val().trim().toUpperCase()
    };


    $(`#productTableMain > tbody > tr`).each((row, tr) => {
        arrangedResult.products.push({
            product: $(tr).find('td:eq(1)').text().trim().toUpperCase(),
            quantity: $(tr).find('td:eq(3)').text().trim().toUpperCase(),
            unit: $(tr).find('td:eq(4)').text().trim().toUpperCase()
        });
    });

    return arrangedResult;
}

function saveShipment() {
    if (isValidShipment()) {
        $('#save-shipment').attr("disable", "true");
        var arrangedCartoon = {};
        let resultCartoon = getCartoonNumber();
        let length = $(`#Input-Length`).val().trim() ? parseFloat($(`#Input-Length`).val().trim()) : 0;
        let width = $(`#Input-Width`).val().trim() ? parseFloat($(`#Input-Width`).val().trim()) : 0;
        let heigth = $(`#Input-Height`).val().trim() ? parseFloat($(`#Input-Height`).val().trim()) : 0;
        let weight = $(`#Input-Weight`).val().trim() ? parseFloat($(`#Input-Weight`).val().trim()) : 0;
        let cbm = CURRENTSHIPMENT.filledcmb;
        let pdfTable = [];
        if (resultCartoon.isRanged) {
            let range = (resultCartoon.end - resultCartoon.start) + 1;
            if (!$(`#Input-AddWithCartoonCount`).prop('checked')) {
                if (length > 0 && width > 0 && heigth > 0) {
                    length /= range;
                    width /= range;
                    heigth /= range;
                }

                if (weight > 0) {
                    weight /= range;
                }
            } else {
                if (length > 0 && width > 0 && heigth > 0) {
                    cbm += ((length * width * heigth) / 1000000) * range;
                }
            }
            for (let i = resultCartoon.start; i <= resultCartoon.end; i++) {
                let carton = `${resultCartoon.prefix}${i}${resultCartoon.profix}`;
                arrangedCartoon[carton] = arragedCartoonPacked(carton, length, width, heigth, weight);
                pdfTable.push(getPDFTable(carton));
                if (i !== resultCartoon.end) {
                    pdfTable.push({ text: '', pageBreak: "before" });
                }
            }
        } else {
            if (length > 0 && width > 0 && heigth > 0) {
                cbm += (length * width * heigth) / 1000000;
            }
            arrangedCartoon[resultCartoon.start] = arragedCartoonPacked(resultCartoon.start, length, width, heigth, weight);
            pdfTable.push(getPDFTable(resultCartoon.start));
        }
        CURRENTSHIPMENT.filledcmb = cbm;
        if (CURRENTSHIPMENT[$('#shipment-status').dropdown('get value')]) {
            CURRENTSHIPMENT[$('#shipment-status').dropdown('get value')] = { cartons: { ...CURRENTSHIPMENT[$('#shipment-status').dropdown('get value')].cartons, ...arrangedCartoon } };
        } else {
            CURRENTSHIPMENT[$('#shipment-status').dropdown('get value')] = { cartons: arrangedCartoon };
        }
        console.log(CURRENTSHIPMENT);
        if (SYSTEMSHIPPINGPROCESS.qr.isGenerate) {
            createQR(pdfTable);
        }
        updateOverview();
        clearInputs();
        updateCBM();
    }
}

function insertStartCartonNumber() {
    let startIndex = 1;
    let activeStatus = $('#shipment-status').dropdown('get value');
    if (CURRENTSHIPMENT && CURRENTSHIPMENT.hasOwnProperty(activeStatus)) {
        let currentCartons = CURRENTSHIPMENT[activeStatus].cartons;
        let asenKeys = Object.keys(currentCartons).sort(numbersAlphAscending);
        let lastIndex = asenKeys[asenKeys.length - 1];
        if (lastIndex) {
            lastIndex = lastIndex.match(/[^\d]+|\d+/g);
            if (lastIndex.length > 1) {
                if (lastIndex[0].match(/^[A-Za-z]+$/)) {
                    startIndex = lastIndex[0].trim().toUpperCase() + (parseInt(lastIndex[1]) + 1);
                } else {
                    startIndex = (parseInt(lastIndex[0]) + 1) + start[1].trim().toUpperCase();
                }
            } else {
                startIndex = parseInt(lastIndex) + 1;
            }
        }
    }
    $(`#Input-Start`).val(startIndex);
}

function getPDFTable(carton) {
    let cartonFontSize = carton.length <= 2 ? 200 : carton.length > 2 && carton.length <= 4 ? 120 : 100;
    return {
        table: {
            widths: ['*', 'auto'],
            body: [
                [{ text: $(`#Input-CustomerName`).val().trim().toUpperCase(), fontSize: 25, bold: true, alignment: 'center', colSpan: 2 }, {}],
                [{ text: carton, fontSize: cartonFontSize, bold: true, alignment: 'center', colSpan: 2 }, {}],
                [{ qr: `${CURRENTSHIPMENT.exporter} ${CURRENTSHIPMENT.index} ${carton}`, fit: '200', border: [true, false, false, true] },
                { image: 'mainImage', width: 140, border: [false, true, true, true], margin: 0 }]
            ]
        },
        layout: QRlayout
    };
}

var QRlayout = {
    hLineWidth: function (i, node) {
        return 0.5;
    },
    vLineWidth: function (i, node) {
        return 0.5;
    },
    hLineColor: function (i, node) {
        return 'gray';
    },
    vLineColor: function (i, node) {
        return 'gray';
    }
};

function createQR(pdfTable) {
    var docDefinition = {
        info: {
            title: `QR for ${$(`#Input-CustomerName`).val().trim().toUpperCase()}`,
            author: 'Asian Cargo',
            subject: 'QR',
            keywords: 'Pupose of Shipment Carton'
        },
        pageSize: 'A5',
        content: pdfTable,
        images: { mainImage: 'data:image/png;base64,' }
    };

    let FILE_NAME = `QR LIST ${CURRENTSHIPMENT.exporter} ${CURRENTSHIPMENT.index}.pdf`;
    pdfMake.createPdf(docDefinition).getDataUrl().then((result) => {
        $('#QR-Pdf').attr('src', result);
        $('#QR-Pdf').attr('download', FILE_NAME);
        $('#QR-Model').modal('show');
        $('#save-shipment').removeAttr("disable");
    });
}

